html, body {
        height: 100% !important;
    }
    body {
        background: url("https://files.catbox.moe/f7usl4.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Làm trong suốt toàn bộ các khối nền */
    div, table, td, th, header, section {
        background-color: transparent !important;
    }

    /* Xóa màu nền xám của ô lịch */
    .VfPpkd-EScbFb-JIbuQc, .MVMVEe, .u5M5Kc, .mv-daynames-table, .tOoZ3c {
        background-color: transparent !important;
    }
}
